// A minimal stand-in for `effect/Context`. A service key is an Effect that
// looks its service up in the current context, as in the real package.
import { make } from "./Effect.js"

export const Service = (key) => {
  // Looked up by the key's current `key` property, as in the real package.
  const self = make(async (context) => {
    if (!context.has(self.key)) throw new Error(`Service not found: ${self.key}`)
    return context.get(self.key)
  })
  self.key = key
  self.of = (service) => service
  self.use = (f) => make(async (context, scope) => f(await self.run(context, scope)).run(context, scope))
  return self
}

export const get = (context, service) => context.get(service.key)
